import{getProductById as t}from"../data.js";import{formatPrice as a}from"../format.js";import{getCart as e,setQuantity as n,removeFromCart as r}from"../store.js";export function renderCart(i){const c=e(),s=Object.keys(c);if(0===s.length)return void(i.innerHTML='\n      <section class="cart-empty">\n        <h1>Your cart is empty</h1>\n        <p><a href="#/" class="btn btn-solid">Browse the catalog</a></p>\n      </section>\n    ');const o=s.map(a=>({product:t(a),qty:c[a]})).filter(t=>t.product),d=o.reduce((t,a)=>t+a.product.price*a.qty,0);i.innerHTML=`\n    <h1>Your cart</h1>\n    <ul class="cart-list">\n      ${o.map(({product:t,qty:e})=>`\n        <li class="cart-item" data-id="${t.id}">\n          <img src="${t.image}" alt="${t.name}" width="96" height="72" loading="lazy" decoding="async">\n          <div class="cart-item-body">\n            <h3><a href="#/product/${t.id}">${t.name}</a></h3>\n            <p class="cart-item-price">${a(t.price)} each</p>\n          </div>\n          <div class="cart-item-qty">\n            <label for="qty-${t.id}" class="visually-hidden">Quantity for ${t.name}</label>\n            <input type="number" id="qty-${t.id}" min="0" value="${e}" inputmode="numeric" class="qty-input" data-id="${t.id}">\n          </div>\n          <p class="cart-item-total">${a(t.price*e)}</p>\n          <button type="button" class="cart-remove" data-id="${t.id}" aria-label="Remove ${t.name} from cart">&times;</button>\n        </li>\n      `).join("")}\n    </ul>\n\n    <div class="cart-summary">\n      <p class="cart-subtotal">Subtotal <span>${a(d)}</span></p>\n      <a href="#/checkout" class="btn btn-solid">Checkout</a>\n    </div>\n  `,i.querySelectorAll(".qty-input").forEach(t=>{t.addEventListener("change",()=>{const a=Math.max(0,parseInt(t.value,10)||0);n(t.dataset.id,a),renderCart(i)})}),i.querySelectorAll(".cart-remove").forEach(t=>{t.addEventListener("click",()=>{r(t.dataset.id),renderCart(i)})})}